<?php require_once __DIR__.'/includes/db.php'; require_once __DIR__.'/includes/config.php'; require_once __DIR__.'/includes/auth.php';
if (!empty($_SESSION['user'])) { header('Location: '.BASE_URL.'user/dashboard.php'); exit; }
if ($_SERVER['REQUEST_METHOD']==='POST') { $name=trim($_POST['name']); $email=trim($_POST['email']); $phone=trim($_POST['phone']); $vehicle=strtoupper(trim($_POST['vehicle_number'])); $password=$_POST['password']; if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$vehicle||strlen($password)<6) flash('error','Complete all fields; password must be at least 6 characters.'); else { $stmt = $mysqli->prepare('SELECT id FROM users WHERE email=? OR vehicle_number=?'); if (!$stmt) { die('Database error: ' . $mysqli->error); } $stmt->bind_param('ss',$email,$vehicle); $stmt->execute(); $result = $stmt->get_result(); if ($result && $result->num_rows) { flash('error','This email or vehicle number is already registered.'); } else { $hash = password_hash($password,PASSWORD_DEFAULT); $stmt = $mysqli->prepare("INSERT INTO users(name,email,phone,vehicle_number,password,role) VALUES(?,?,?,?,?,'user')"); if (!$stmt) { die('Database error: ' . $mysqli->error); } $stmt->bind_param('sssss',$name,$email,$phone,$vehicle,$hash); $stmt->execute(); flash('success','Registration complete. Please log in.'); header('Location: '.BASE_URL.'login.php'); exit; } } }
$page_title='Create account'; require __DIR__.'/includes/header.php'; ?>
<div class="row justify-content-center"><div class="col-md-7 col-lg-6"><div class="card shadow-sm border-0"><div class="card-body p-4"><h2>Create your account</h2><p class="text-muted">Book a parking space in seconds.</p><form method="post" class="row g-3"><div class="col-12"><label class="form-label">Full name</label><input class="form-control" name="name" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone"></div><div class="col-12"><label class="form-label">Vehicle number</label><input class="form-control" name="vehicle_number" placeholder="MH 12 AB 1234" required></div><div class="col-12"><label class="form-label">Password</label><input class="form-control" type="password" name="password" minlength="6" required></div><div class="col-12"><button class="btn btn-primary w-100">Register</button></div></form></div></div></div></div><?php require __DIR__.'/includes/footer.php'; ?>
